:root {
  --bg: #1e1a2e;
  --bg-card: #2a2440;
  --accent-gold: #c9a84c;
  --accent-amber: #e8c97a;
  --accent-rose: #c4607a;
  --text-primary: #ede8d8;
  --text-muted: #9a93b0;
  --text-dim: #6a6480;
  --border-subtle: #3d3660;
  --tag-bg: #352e55;
  --dial-bg: #211d35;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.star-card {
  background-color: var(--bg-card);
  border: 2px solid var(--accent-gold);
  border-radius: 6px;
  width: 480px;
  padding: 0;
  overflow: hidden;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg);
  border-bottom: 1px solid var(--accent-gold);
  padding: 8px 16px;
}

.card-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.card-date {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 400;
}

.card-body {
  display: flex;
  flex-direction: row;
  gap: 0;
}

.star-dial {
  position: relative;
  width: 148px;
  min-width: 148px;
  height: 180px;
  background-color: var(--dial-bg);
  border-right: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
}

.dial-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid var(--text-dim);
}

.dial-outer {
  width: 110px;
  height: 110px;
  border-color: var(--accent-gold);
  opacity: 0.5;
}

.dial-inner {
  width: 70px;
  height: 70px;
  border-color: var(--text-dim);
  opacity: 0.7;
}

.dial-cross {
  position: absolute;
  width: 110px;
  height: 110px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cross-h {
  position: absolute;
  width: 110px;
  height: 1px;
  background-color: var(--text-dim);
  opacity: 0.4;
}

.cross-v {
  position: absolute;
  width: 1px;
  height: 110px;
  background-color: var(--text-dim);
  opacity: 0.4;
}

.star {
  position: absolute;
  font-size: 14px;
  color: var(--accent-amber);
}

.star-a {
  top: 24px;
  left: 30px;
  font-size: 18px;
  color: var(--accent-gold);
}

.star-b {
  top: 40px;
  right: 28px;
  font-size: 11px;
  color: var(--text-muted);
}

.star-c {
  bottom: 32px;
  left: 42px;
  font-size: 12px;
  color: var(--accent-amber);
}

.star-d {
  bottom: 28px;
  right: 24px;
  font-size: 16px;
  color: var(--accent-rose);
}

.card-data {
  flex: 1;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.data-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  border-bottom: 1px dashed var(--border-subtle);
  padding-bottom: 5px;
}

.data-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--text-dim);
}

.data-value {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
}

.data-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.tag {
  background-color: var(--tag-bg);
  border: 1px solid var(--border-subtle);
  border-radius: 3px;
  padding: 2px 8px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: var(--accent-amber);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg);
  border-top: 1px solid var(--border-subtle);
  padding: 7px 16px;
}

.footer-obs {
  font-size: 10px;
  color: var(--text-muted);
}

.footer-instrument {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-gold);
  letter-spacing: 0.5px;
}
